import { createRoot } from 'react-dom/client';
import { ArrowLeft, ArrowRight, AtSign as Instagram, Award, BadgeCheck, BarChart3, Bell, CalendarDays, Camera, Check, ChevronLeft, Clock3, DollarSign, Eye, EyeOff, FileBadge, Heart, ImagePlus, LayoutDashboard, Lock, LogIn, MapPin, Menu, MessageCircle, Phone, Play, Plus, Save, Scissors, Search, Settings, ShieldCheck, Sparkles, Star, Trash2, UploadCloud, UserPlus, UserRound, UsersRound, Video, X } from 'lucide-react';
