const initialServices = [];
const initialCertificates = [];
const initialStaff = [];
const initialMedia = [];
const iconMap = { sparkles: Sparkles, heart: Heart, scissors: Scissors, star: Star };
const fa = value => Number(value).toLocaleString('fa-IR');
const latin = value => String(value).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d));
const dateKey = date => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const persianFormatter = new Intl.DateTimeFormat('fa-IR-u-ca-persian-nu-latn', { year:'numeric', month:'numeric', day:'numeric', weekday:'long' });
const persianParts = date => Object.fromEntries(persianFormatter.formatToParts(date).filter(x=>x.type!=='literal').map(x=>[x.type,x.value]));
const formatPersian = date => new Intl.DateTimeFormat('fa-IR-u-ca-persian',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(date);
const monthTitle = date => new Intl.DateTimeFormat('fa-IR-u-ca-persian',{month:'long',year:'numeric'}).format(date);
function getMonthGrid(anchor){const parts=persianParts(anchor),first=new Date(anchor);first.setHours(12,0,0,0);first.setDate(first.getDate()-Number(parts.day)+1);const days=[];for(let i=0;i<32;i++){const d=new Date(first);d.setDate(first.getDate()+i);const p=persianParts(d);if(p.month!==parts.month)break;days.push(d)}return{title:monthTitle(first),days:[...Array((first.getDay()+1)%7).fill(null),...days]}}
function shiftPersianMonth(anchor,delta){const current=persianParts(anchor),d=new Date(anchor);d.setHours(12,0,0,0);if(delta>0){do d.setDate(d.getDate()+1);while(persianParts(d).month===current.month&&persianParts(d).year===current.year)}else{d.setDate(d.getDate()-Number(current.day));}return d}
const scrollToId=id=>document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'});

function Logo({compact=false}){return <button className={`brand ${compact?'compact':''}`} onClick={()=>scrollToId('home')} aria-label="خانه"><img src="/assets/baran-logo.png" alt="لوگوی سالن زیبایی باران"/>{!compact&&<span><strong>سالن زیبایی باران</strong><small>BEAUTY SALON</small></span>}</button>}
function Header({onBooking,onAdmin}){const[open,setOpen]=useState(false);const nav=[['services','خدمات'],['about','درباره باران'],['team','تیم ما'],['credentials','مدارک و افتخارات'],['contact','تماس با ما']];return <header className="header"><div className="nav-wrap container"><Logo/><nav className={open?'open':''}>{nav.map(([id,label])=><button key={id} onClick={()=>{scrollToId(id);setOpen(false)}}>{label}</button>)}<button className="admin-link" onClick={onAdmin}><LayoutDashboard size={17}/> پنل مدیریت</button></nav><button className="primary-btn header-cta" onClick={onBooking}><CalendarDays size={18}/> رزرو نوبت</button><button className="menu-btn" onClick={()=>setOpen(!open)}>{open?<X/>:<Menu/>}</button></div></header>}
const slides=[{image:'/assets/hero-salon.jpg',eyebrow:'به دنیای زیبایی باران خوش آمدید',title:<>زیبایی تو،<br/><em>امضای ماست</em></>,text:'تجربه‌ای آرام، حرفه‌ای و شخصی‌سازی‌شده؛ جایی که هر جزئیات برای درخشش تو طراحی شده است.'},{image:'/assets/hero-hair.jpg',eyebrow:'سلامت و درخشش موهای شما',title:<>هنرِ رنگ،<br/><em>ظرافتِ اجرا</em></>,text:'از مشاوره رنگ تا اجرای نهایی، همراهت هستیم تا بهترین نسخه خودت را پیدا کنی.'},{image:'/assets/hero-bridal.jpg',eyebrow:'برای خاص‌ترین روز زندگی',title:<>درخششِ ماندگار،<br/><em>حسِ خوب تو</em></>,text:'میکاپ و استایل اختصاصی عروس با برنامه‌ریزی دقیق و آرامش خیال.'}];
function Hero({onBooking}){const[active,setActive]=useState(0);useEffect(()=>{const id=setInterval(()=>setActive(a=>(a+1)%slides.length),6500);return()=>clearInterval(id)},[]);const move=d=>setActive(a=>(a+d+slides.length)%slides.length);return <section id="home" className="hero">{slides.map((s,i)=><div key={s.image} className={`hero-slide ${i===active?'active':''}`} style={{backgroundImage:`url(${s.image})`}}/>)}<div className="hero-shade"/><div className="hero-content container"><div className="hero-copy"><span className="eyebrow"><Sparkles size={17}/>{slides[active].eyebrow}</span><h1>{slides[active].title}</h1><p>{slides[active].text}</p><div className="hero-actions"><button className="primary-btn large" onClick={onBooking}>رزرو آنلاین <ArrowLeft size={19}/></button><button className="ghost-btn" onClick={()=>scrollToId('services')}>مشاهده خدمات</button></div><div className="trust-row"><span><BadgeCheck/> مواد اورجینال</span><span><ShieldCheck/> رعایت کامل بهداشت</span><span><Star/> تیم حرفه‌ای</span></div></div></div><div className="slide-controls"><button onClick={()=>setAnchor(a=>shiftPersianMonth(a,-1))}><ArrowRight/></button><div>{slides.map((_,i)=><button key={i} className={i===active?'active':''} onClick={()=>setActive(i)}/>)}</div><button onClick={()=>setAnchor(a=>shiftPersianMonth(a,1))}><ArrowLeft/></button></div><div className="hero-card"><span>اولین باره مهمان مایی؟</span><strong>مشاوره اولیه رایگان</strong><button onClick={onBooking}>دریافت مشاوره <ChevronLeft size={17}/></button></div></section>}
function SectionTitle({overline,title,text}){return <div className="section-title"><span>{overline}</span><h2>{title}</h2>{text&&<p>{text}</p>}</div>}
function Services({services,onBooking}){const tints=['rose','peach','sand','mauve'];return <section id="services" className="section services"><div className="container"><SectionTitle overline="خدمات ما" title="هر آنچه برای درخشش نیاز داری" text="خدمات حرفه‌ای متناسب با نیاز و سبک شخصی تو؛ قیمت نهایی پس از مشاوره مشخص می‌شود."/><div className="service-grid">{services.filter(x=>x.active).map((s,i)=>{const Icon=iconMap[s.icon]||Sparkles;return <article className="service-card clickable" key={s.id} onClick={onBooking}><div className={`service-icon ${tints[i%4]}`}><Icon/></div><span className="service-no">{fa(i+1)}</span><h3>{s.title}</h3><p>{s.desc}</p><div className="service-meta"><span><Clock3/>{fa(s.duration)} دقیقه</span><strong>شروع از {s.price} تومان</strong></div><button>انتخاب و رزرو <ArrowLeft/></button></article>})}</div></div></section>}
function About({onVideo}){return <section id="about" className="section about"><div className="container about-grid"><div className="about-media"><img src="/assets/hero-salon.jpg" alt="نمای داخلی سالن باران"/><button className="play-chip" onClick={onVideo}><span><Play fill="currentColor"/></span><div><strong>داستان باران</strong><small>تماشای ویدئوی معرفی</small></div></button></div><div className="about-copy"><SectionTitle overline="درباره سالن باران" title="اینجا، زیبایی با آرامش همراه است"/><p>باران با یک باور ساده شکل گرفت: هر بانویی شایسته‌ی تجربه‌ای منحصربه‌فرد از زیبایی است. فضایی امن، آرام و صمیمی ساخته‌ایم تا با خیال راحت، خودت باشی و بدرخشی.</p><div className="about-points"><div><BadgeCheck/><span><strong>تجربه شخصی‌سازی‌شده</strong><small>مشاوره اختصاصی قبل از شروع هر خدمت</small></span></div><div><Sparkles/><span><strong>کیفیت بدون مصالحه</strong><small>محصولات معتبر و تجهیزات به‌روز</small></span></div></div><button className="text-btn" onClick={()=>scrollToId('credentials')}>رزومه و مدارک ما <ArrowLeft/></button></div></div></section>}
function Team({staff,onSelect}){return <section id="team" className="section team"><div className="container"><SectionTitle overline="تیم حرفه‌ای باران" title="هنرمندانی که به تو گوش می‌دهند" text="برای دیدن مشخصات هر متخصص، کارت او را انتخاب کنید."/><div className="staff-grid">{staff.map(p=><article className="staff-card clickable" key={p.id} onClick={()=>onSelect(p)}><div className="staff-photo"><img src={p.img} alt={p.name}/><span><Instagram/></span></div><div><h3>{p.name}</h3><p>{p.role}</p><small>{p.years}</small></div><button><ArrowLeft/></button></article>)}</div></div></section>}
function Credentials({certificates,onSelect}){return <section id="credentials" className="section credentials"><div className="container credentials-grid"><div><SectionTitle overline="رزومه و گواهینامه‌ها" title="تجربه‌ای که می‌توانی به آن اعتماد کنی"/><p>برای مشاهده صادرکننده، کد مدرک، مهارت‌های کسب‌شده و تصویر هر گواهینامه، روی آن کلیک کنید.</p><div className="stats"><div><strong>{fa(certificates.length)}</strong><span>مدرک ثبت‌شده</span></div></div></div><div className="certificate-list">{certificates.map(c=><button className="certificate-item" key={c.id} onClick={()=>onSelect(c)}><div className="cert-icon"><FileBadge/></div><div><h3>{c.title}</h3><p>{c.issuer}</p><span>دریافت در سال {c.year} · مشاهده جزئیات</span></div><ArrowLeft/></button>)}</div></div></section>}
function Gallery({media,onSelect}){return <section className="section gallery"><div className="container"><div className="gallery-head"><SectionTitle overline="گالری باران" title="لحظه‌هایی از زیبایی"/><a href="https://instagram.com/baranbeauty_official" target="_blank" rel="noreferrer"><Instagram/> baranbeauty_official</a></div><div className="gallery-grid">{media.slice(0,4).map(m=><button key={m.id} onClick={()=>onSelect(m)} className={m.type==='video'?'video-tile':''}>{m.type==='video'&&m.src?.startsWith('blob:')?<video src={m.src} muted preload="metadata"/>:<img src={m.src} alt={m.name}/>} {m.type==='video'&&<b><Play fill="currentColor"/></b>}<span>{m.type==='video'?<Video/>:<Camera/>} {m.type==='video'?'پخش ویدئو':'مشاهده تصویر'}</span></button>)}</div></div></section>}
function Contact({salon}){return <section id="contact" className="section contact"><div className="container contact-card"><div className="contact-copy"><SectionTitle overline="منتظر دیدارت هستیم" title="اطلاعات سالن"/><p>{salon?.about||'اطلاعات سالن هنوز توسط مدیر ثبت نشده است.'}</p><div className="contact-items"><div><MapPin/><span><strong>آدرس سالن</strong><small>{salon?.address||'ثبت نشده'}</small></span></div><div><Phone/><span><strong>شماره تماس</strong><small>{[salon?.phone,salon?.mobile].filter(Boolean).join(' | ')||'ثبت نشده'}</small></span></div><div><Clock3/><span><strong>ساعات کاری</strong><small>{salon?`${salon.opensAt?.slice(0,5)} تا ${salon.closesAt?.slice(0,5)}`:'ثبت نشده'}</small></span></div></div></div><div className="map-mock"><div className="map-lines"/><span className="map-pin"><MapPin fill="currentColor"/></span><div className="map-label"><img src="/assets/baran-logo.png"/><div><strong>{salon?.name||'سالن زیبایی باران'}</strong><small>{salon?.address||'آدرس ثبت نشده'}</small></div></div></div></div></section>}
function BookingModal({services,blockedDates,onClose}){const available=services.filter(x=>x.active);const[step,setStep]=useState(1),[service,setService]=useState(available[0]?.id),[day,setDay]=useState(null),[time,setTime]=useState('۱۱:۳۰');const dates=useMemo(()=>Array.from({length:14},(_,i)=>{const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+i);return d}).filter(d=>d.getDay()!==5&&!blockedDates.includes(dateKey(d))).slice(0,7),[blockedDates]);useEffect(()=>{if(!day&&dates[0])setDay(dates[0])},[dates,day]);const picked=available.find(x=>x.id===service)||available[0];return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="booking-modal"><div className="modal-head"><div><span>رزرو آنلاین</span><h2>{step===4?'نوبت شما ثبت شد':'وقت درخشش تو رسیده'}</h2></div><button onClick={onClose}><X/></button></div>{step<4&&<div className="steps">{['انتخاب خدمت','زمان نوبت','اطلاعات شما'].map((x,i)=><div className={step>=i+1?'active':''} key={x}><span>{step>i+1?<Check/>:fa(i+1)}</span><small>{x}</small></div>)}</div>}<div className="modal-body">{step===1&&<><p className="prompt">کدام خدمت را برایت رزرو کنیم؟</p><div className="booking-services">{available.map(s=>{const Icon=iconMap[s.icon]||Sparkles;return <button key={s.id} className={service===s.id?'selected':''} onClick={()=>setService(s.id)}><Icon/><span><strong>{s.title}</strong><small>{fa(s.duration)} دقیقه · شروع از {s.price} تومان</small></span>{service===s.id&&<Check/>}</button>})}</div></>}{step===2&&<><p className="prompt">روز و ساعت مناسب را انتخاب کن</p><div className="live-date-note"><CalendarDays/><span>تقویم شمسی به‌روز · امروز {formatPersian(new Date())}</span></div><div className="day-row modern">{dates.map(d=><button key={dateKey(d)} className={day&&dateKey(day)===dateKey(d)?'selected':''} onClick={()=>setDay(d)}><small>{new Intl.DateTimeFormat('fa-IR',{weekday:'short'}).format(d)}</small><strong>{new Intl.DateTimeFormat('fa-IR-u-ca-persian',{day:'numeric'}).format(d)}</strong><em>{new Intl.DateTimeFormat('fa-IR-u-ca-persian',{month:'short'}).format(d)}</em></button>)}</div><div className="times">{['۱۰:۰۰','۱۱:۳۰','۱۳:۰۰','۱۵:۳۰','۱۷:۰۰','۱۸:۳۰'].map(t=><button className={time===t?'selected':''} onClick={()=>setTime(t)} key={t}>{t}</button>)}</div></>}{step===3&&<><p className="prompt">اطلاعات تماس را وارد کن</p><div className="form-grid"><label><span>نام و نام خانوادگی</span><input placeholder="مثلاً نازنین احمدی"/></label><label><span>شماره موبایل</span><input dir="ltr" placeholder="0912 123 4567"/></label><label className="full"><span>توضیحات</span><textarea placeholder="اگر نکته‌ای هست برایمان بنویس..."/></label></div><div className="booking-summary"><span><Sparkles/></span><div><strong>{picked?.title}</strong><small>{day&&formatPersian(day)} · ساعت {time}</small></div><b>شروع از {picked?.price} تومان</b></div></>}{step===4&&<div className="success"><div><Check/></div><h3>تا دیدار تو لحظه‌شماری می‌کنیم!</h3><p>جزئیات نوبت برای شماره موبایل شما ارسال می‌شود.</p><article><span><CalendarDays/></span><div><strong>{picked?.title}</strong><small>{day&&formatPersian(day)}، ساعت {time}</small></div></article><button className="primary-btn" onClick={onClose}>بازگشت به صفحه اصلی</button></div>}</div>{step<4&&<div className="modal-foot"><button className="back-btn" onClick={()=>step===1?onClose():setStep(step-1)}>{step===1?'انصراف':'مرحله قبل'}</button><button className="primary-btn" onClick={()=>setStep(step+1)}>{step===3?'تأیید نهایی رزرو':'ادامه'} <ArrowLeft/></button></div>}</div></div>}
function ApiBookingModal({services,blockedDates,onClose}){const available=services.filter(x=>x.active),dates=Array.from({length:14},(_,i)=>{const d=new Date();d.setDate(d.getDate()+i+1);d.setHours(12,0,0,0);return d}).filter(d=>d.getDay()!==5&&!blockedDates.includes(dateKey(d))).slice(0,7);const[step,setStep]=useState(1),[service,setService]=useState(available[0]?.id),[day,setDay]=useState(dates[0]),[time,setTime]=useState('۱۱:۳۰'),[name,setName]=useState(''),[mobile,setMobile]=useState(''),[notes,setNotes]=useState(''),[error,setError]=useState(''),[saving,setSaving]=useState(false);const picked=available.find(x=>x.id===service);const submit=async()=>{if(!name.trim()||mobile.trim().length<10){setError('نام و شماره موبایل معتبر وارد کنید.');return}try{setSaving(true);setError('');const[hour,minute]=latin(time).split(':').map(Number),startsAt=new Date(day);startsAt.setHours(hour,minute,0,0);await api.createAppointment({serviceId:service,customerName:name,mobile,startsAt:startsAt.toISOString(),notes});setStep(4)}catch(err){setError(err.message)}finally{setSaving(false)}};return <div className="modal-backdrop"><div className="booking-modal"><div className="modal-head"><div><span>رزرو آنلاین</span><h2>{step===4?'نوبت شما ثبت شد':'وقت درخشش تو رسیده'}</h2></div><button onClick={onClose}><X/></button></div>{step<4&&<div className="steps">{['انتخاب خدمت','زمان نوبت','اطلاعات شما'].map((x,i)=><div className={step>=i+1?'active':''} key={x}><span>{step>i+1?<Check/>:fa(i+1)}</span><small>{x}</small></div>)}</div>}<div className="modal-body">{step===1&&<div className="booking-services">{available.map(s=><button key={s.id} className={service===s.id?'selected':''} onClick={()=>setService(s.id)}><Sparkles/><span><strong>{s.title}</strong><small>{fa(s.duration)} دقیقه · شروع از {s.price} تومان</small></span>{service===s.id&&<Check/>}</button>)}</div>}{step===2&&<><div className="live-date-note"><CalendarDays/> تقویم شمسی به‌روز · امروز {formatPersian(new Date())}</div><div className="day-row modern">{dates.map(d=><button key={dateKey(d)} className={dateKey(day)===dateKey(d)?'selected':''} onClick={()=>setDay(d)}><small>{new Intl.DateTimeFormat('fa-IR',{weekday:'short'}).format(d)}</small><strong>{new Intl.DateTimeFormat('fa-IR-u-ca-persian',{day:'numeric'}).format(d)}</strong><em>{new Intl.DateTimeFormat('fa-IR-u-ca-persian',{month:'short'}).format(d)}</em></button>)}</div><div className="times">{['۱۰:۰۰','۱۱:۳۰','۱۳:۰۰','۱۵:۳۰','۱۷:۰۰','۱۸:۳۰'].map(t=><button className={time===t?'selected':''} onClick={()=>setTime(t)} key={t}>{t}</button>)}</div></>}{step===3&&<><div className="form-grid"><label><span>نام و نام خانوادگی</span><input value={name} onChange={e=>setName(e.target.value)}/></label><label><span>شماره موبایل</span><input value={mobile} onChange={e=>setMobile(e.target.value)} dir="ltr"/></label><label className="full"><span>توضیحات</span><textarea value={notes} onChange={e=>setNotes(e.target.value)}/></label></div>{error&&<div className="login-error">{error}</div>}<div className="booking-summary"><span><Sparkles/></span><div><strong>{picked?.title}</strong><small>{formatPersian(day)} · ساعت {time}</small></div></div></>}{step===4&&<div className="success"><div><Check/></div><h3>نوبت با موفقیت ثبت شد</h3><p>مدیر سالن می‌تواند نوبت شما را در پنل مدیریت مشاهده کند.</p><button className="primary-btn" onClick={onClose}>بازگشت به سایت</button></div>}</div>{step<4&&<div className="modal-foot"><button className="back-btn" onClick={()=>step===1?onClose():setStep(step-1)}>{step===1?'انصراف':'مرحله قبل'}</button><button className="primary-btn" disabled={saving} onClick={()=>step===3?submit():setStep(step+1)}>{saving?'در حال ثبت...':step===3?'ثبت نهایی نوبت':'ادامه'} <ArrowLeft/></button></div>}</div></div>}

function DetailModal({item,onClose}){if(!item)return null;const isCert=!!item.issuer,isStaff=!!item.role,isVideo=item.type==='video',source=item.image||item.img||item.src,isUploadedVideo=isVideo&&source?.startsWith('blob:');return <div className="modal-backdrop detail-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="detail-modal"><button className="detail-close" onClick={onClose}><X/></button><div className={`detail-visual ${isVideo?'video-preview':''}`}>{isUploadedVideo?<video src={source} controls autoPlay/>:<img src={source} alt={item.title||item.name}/>} {isVideo&&!isUploadedVideo&&<div className="video-overlay"><span><Play fill="currentColor"/></span><strong>ویدئوی معرفی سالن باران</strong><small>فایل معرفی از پنل مدیریت قابل جایگزینی است</small></div>}</div><div className="detail-content"><span className="eyebrow"><Award/>{isCert?'مدرک و گواهینامه':isStaff?'عضو تیم باران':'گالری باران'}</span><h2>{item.title||item.name}</h2>{isCert&&<><p>{item.description}</p><div className="credential-meta"><span><strong>صادرکننده</strong>{item.issuer}</span><span><strong>سال دریافت</strong>{item.year}</span><span><strong>کد اعتبار</strong>{item.code}</span></div><h4>مهارت‌های تأییدشده</h4><div className="skill-tags">{item.skills?.map(x=><span key={x}><Check/>{x}</span>)}</div></>}{isStaff&&<p>{item.role} با {item.years} و سابقه اجرای خدمات تخصصی متناسب با فرم چهره و سبک شخصی مراجعه‌کنندگان.</p>}{!isCert&&!isStaff&&<p>برای مشاهده نمونه‌کارهای بیشتر و دریافت مشاوره با سالن باران در ارتباط باشید.</p>}</div></div></div>}

function AdminLogin({onSuccess,onClose}){const[user,setUser]=useState(''),[pass,setPass]=useState(''),[show,setShow]=useState(false),[error,setError]=useState(''),[loading,setLoading]=useState(false);const submit=async e=>{e.preventDefault();setError('');if(!user.trim()||pass.length<4){setError('نام کاربری و رمز عبور معتبر وارد کنید.');return}try{setLoading(true);await api.login(user,pass);onSuccess()}catch(err){setError(err.message)}finally{setLoading(false)}};return <div className="admin-login"><div className="login-visual"><div><img src="/assets/baran-logo.png"/><span>مدیریت یکپارچه سالن زیبایی باران</span><h1>همه‌چیز، دقیق و در دسترس</h1><p>نوبت‌ها، خدمات، رسانه‌ها، پرسنل و محتوای سایت را از یک پنل مدیریت کنید.</p></div></div><div className="login-form-wrap"><button className="login-back" onClick={onClose}><ArrowRight/> بازگشت به سایت</button><form onSubmit={submit}><div className="login-logo"><Logo/><span>ورود مدیر</span></div><h2>خوش آمدید</h2><p>برای ورود به پنل مدیریت، اطلاعات حساب خود را وارد کنید.</p><label><span>نام کاربری</span><div><UserRound/><input value={user} onChange={e=>setUser(e.target.value)} autoComplete="username" placeholder="نام کاربری"/></div></label><label><span>رمز عبور</span><div><Lock/><input value={pass} onChange={e=>setPass(e.target.value)} type={show?'text':'password'} autoComplete="current-password" placeholder="رمز عبور"/><button type="button" onClick={()=>setShow(!show)}>{show?<EyeOff/>:<Eye/>}</button></div></label>{error&&<div className="login-error">{error}</div>}<button className="primary-btn login-submit" disabled={loading}><LogIn/> {loading?'در حال ورود...':'ورود به پنل'}</button><small><ShieldCheck/> اطلاعات ورود به‌صورت امن بررسی می‌شود.</small></form></div></div>}
function AdminPanel(props){const[authenticated,setAuthenticated]=useState(false),[tab,setTab]=useState('overview'),[toast,setToast]=useState('');const notify=msg=>{setToast(msg);setTimeout(()=>setToast(''),2200)};if(!authenticated)return <AdminLogin onSuccess={()=>setAuthenticated(true)} onClose={props.onClose}/>;const menu=[['overview','نمای کلی',LayoutDashboard],['appointments','نوبت‌ها',CalendarDays],['calendar','تقویم کاری',Clock3],['services','خدمات و قیمت‌ها',Scissors],['media','رسانه‌ها',ImagePlus],['certificates','رزومه و مدارک',Award],['staff','پرسنل',UsersRound],['settings','اطلاعات سالن',Settings],['sms','تنظیمات پیامک',MessageCircle]];return <div className="admin-shell" dir="rtl"><aside><div className="admin-brand"><Logo compact/><span><strong>مدیریت باران</strong><small>سامانه مدیریت سالن</small></span></div><nav>{menu.map(([id,label,I])=><button className={tab===id?'active':''} onClick={()=>setTab(id)} key={id}><I/>{label}</button>)}</nav><button className="exit-admin" onClick={props.onClose}><ArrowRight/> بازگشت به سایت</button></aside><main><header><div><small>پنل مدیریت / {menu.find(x=>x[0]===tab)?.[1]}</small><h1>{menu.find(x=>x[0]===tab)?.[1]}</h1></div><div className="admin-head-actions"><button><Search/></button><button><Bell/></button><div className="admin-user"><span>ب‌م</span><div><strong>باران محمودی</strong><small>مدیر سالن</small></div></div></div></header>{tab==='overview'&&<ApiDashboard setTab={setTab} services={props.services} staff={props.staff} blockedDates={props.blockedDates}/>} {tab==='appointments'&&<ApiAppointments/>} {tab==='calendar'&&<ApiAdminCalendar blockedDates={props.blockedDates} setBlockedDates={props.setBlockedDates} blockedItems={props.blockedItems} setBlockedItems={props.setBlockedItems} notify={notify}/>} {tab==='services'&&<ApiServiceManager services={props.services} setServices={props.setServices} notify={notify}/>} {tab==='media'&&<ApiMediaManager media={props.media} setMedia={props.setMedia} notify={notify}/>} {tab==='certificates'&&<ApiCertificateManager certificates={props.certificates} setCertificates={props.setCertificates} notify={notify}/>} {tab==='staff'&&<ApiStaffManager staff={props.staff} setStaff={props.setStaff} notify={notify}/>} {tab==='settings'&&<ApiSalonSettings notify={notify}/>} {tab==='sms'&&<ApiSmsSettings notify={notify}/>} {toast&&<div className="admin-toast"><Check/>{toast}</div>}</main></div>}
function AdminAppointments({full=false}){const rows=[['۱۰:۰۰','مریم رضایی','رنگ و لایت','تأیید شده'],['۱۱:۳۰','نگار حسینی','کوتاهی و استایل','در انتظار'],['۱۳:۰۰','آوا کریمی','میکاپ و گریم','تأیید شده'],['۱۵:۳۰','سارا محمدی','خدمات ناخن','تأیید شده']];return <section className={`panel appointments ${full?'full':''}`}><div className="panel-title"><div><h3>نوبت‌های امروز</h3><small>{formatPersian(new Date())}</small></div><button>مشاهده همه <ArrowLeft/></button></div><div className="appointment-list">{rows.map(r=><article key={r[0]}><time>{r[0]}</time><span className="avatar">{r[1][0]}</span><div><strong>{r[1]}</strong><small>{r[2]}</small></div><em className={r[3]==='تأیید شده'?'ok':'pending'}>{r[3]}</em><button>•••</button></article>)}</div></section>}
function AdminCalendar({blockedDates,setBlockedDates,notify}){const[anchor,setAnchor]=useState(new Date());const grid=getMonthGrid(anchor),today=dateKey(new Date());const toggle=d=>{const k=dateKey(d);setBlockedDates(x=>x.includes(k)?x.filter(y=>y!==k):[...x,k])};const move=n=>{const d=new Date(anchor);d.setDate(15);d.setMonth(d.getMonth()+n);setAnchor(d)};return <section className="panel calendar-panel"><div className="panel-title"><div><h3>تنظیم روزهای قابل رزرو</h3><small>تقویم شمسی پویا؛ جمعه‌ها به‌صورت خودکار تعطیل‌اند.</small></div><div className="legend"><span><i/>قابل رزرو</span><span><i className="off"/>غیرفعال</span></div></div><div className="admin-calendar"><div className="calendar-header"><button onClick={()=>setAnchor(a=>shiftPersianMonth(a,-1))}><ChevronLeft/></button><h2>{grid.title}</h2><button onClick={()=>setAnchor(a=>shiftPersianMonth(a,1))}><ChevronLeft className="flip"/></button></div><div className="weekdays">{['شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه'].map(x=><span key={x}>{x}</span>)}</div><div className="month-days">{grid.days.map((d,i)=>d?<button className={`${blockedDates.includes(dateKey(d))||d.getDay()===5?'blocked':''} ${dateKey(d)===today?'today':''}`} onClick={()=>d.getDay()!==5&&toggle(d)} key={dateKey(d)} disabled={d.getDay()===5}><strong>{new Intl.DateTimeFormat('fa-IR-u-ca-persian',{day:'numeric'}).format(d)}</strong><small>{d.getDay()===5?'تعطیل':blockedDates.includes(dateKey(d))?'غیرفعال':'قابل رزرو'}</small></button>:<span className="empty-day" key={i}/>)}</div></div><div className="calendar-note"><ShieldCheck/><span><strong>{fa(blockedDates.length)} روز غیرفعال ثبت شده</strong><small>این روزها در فرم رزرو کاربران نمایش داده نمی‌شوند.</small></span><button className="primary-btn" onClick={()=>notify('تقویم کاری ذخیره شد')}>ذخیره تغییرات</button></div></section>}
function ApiServiceManager({services,setServices,notify}){const empty={title:'',desc:'',price:'',duration:60,icon:'sparkles',active:true};const[form,setForm]=useState(empty);const add=async e=>{e.preventDefault();try{const created=await api.addService(form);setServices(x=>[...x,created]);setForm(empty);notify('خدمت در سرور ذخیره شد')}catch(err){notify(err.message)}};const remove=async id=>{await api.deleteService(id);setServices(x=>x.filter(y=>y.id!==id));notify('خدمت حذف شد')};const toggle=async s=>{const next={...s,active:!s.active};await api.setService(s.id,next);setServices(x=>x.map(y=>y.id===s.id?next:y))};return <div className="manager-layout"><section className="panel manager-form"><h3>تعریف خدمت جدید</h3><form onSubmit={add}><label><span>عنوان خدمت</span><input value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label><label><span>شروع قیمت (تومان)</span><input value={form.price} onChange={e=>setForm({...form,price:e.target.value})}/></label><div className="inline-fields"><label><span>مدت تقریبی</span><input type="number" value={form.duration} onChange={e=>setForm({...form,duration:Number(e.target.value)})}/></label><label><span>دسته‌بندی</span><select value={form.icon} onChange={e=>setForm({...form,icon:e.target.value})}><option value="sparkles">مو و رنگ</option><option value="heart">میکاپ</option><option value="scissors">کوتاهی</option><option value="star">ناخن</option></select></label></div><label><span>توضیحات</span><textarea value={form.desc} onChange={e=>setForm({...form,desc:e.target.value})}/></label><button className="primary-btn"><Plus/> افزودن خدمت</button></form></section><section className="panel manager-list"><h3>خدمات ذخیره‌شده</h3>{services.map(s=><article className="manage-row" key={s.id}><span className="manage-icon"><Scissors/></span><div><strong>{s.title}</strong><small>شروع از {s.price} تومان · {fa(s.duration)} دقیقه</small></div><button className={`switch ${s.active?'on':''}`} onClick={()=>toggle(s)}/><button className="icon-btn danger" onClick={()=>remove(s.id)}><Trash2/></button></article>)}</section></div>}

function ApiMediaManager({media,setMedia,notify}){const upload=async e=>{try{const added=[];for(const file of e.target.files)added.push(await api.upload(file,'gallery'));setMedia(x=>[...added,...x]);notify('رسانه‌ها روی سرور بارگذاری شدند')}catch(err){notify(err.message)}};const remove=async id=>{await api.deleteMedia(id);setMedia(x=>x.filter(y=>y.id!==id))};return <section className="panel media-panel"><label className="dropzone"><input type="file" accept="image/*,video/*" multiple onChange={upload}/><UploadCloud/><h3>بارگذاری تصویر و ویدئو روی سرور</h3><p>فایل‌های انتخاب‌شده در کتابخانه رسانه ذخیره می‌شوند.</p></label><div className="media-grid">{media.map(m=><article key={m.id}>{m.type==='video'?<video src={m.src}/>:<img src={m.src} alt={m.name}/>}<div><small>{m.name}</small><button onClick={()=>remove(m.id)}><Trash2/></button></div></article>)}</div></section>}

function ApiAppointments(){const[items,setItems]=useState([]),[error,setError]=useState('');useEffect(()=>{api.getAppointments().then(setItems).catch(e=>setError(e.message))},[]);return <section className="panel appointments full"><div className="panel-title"><h3>نوبت‌های ثبت‌شده در سرور</h3><small>{fa(items.length)} نوبت</small></div>{error&&<div className="login-error">{error}</div>}<div className="appointment-list">{items.map(x=><article key={x.id}><time>{new Date(x.startsAt).toLocaleTimeString('fa-IR',{hour:'2-digit',minute:'2-digit'})}</time><span className="avatar">{x.customerName?.[0]}</span><div><strong>{x.customerName}</strong><small>{x.serviceTitle} · {new Date(x.startsAt).toLocaleDateString('fa-IR-u-ca-persian')}</small></div><em className="ok">{x.status}</em></article>)}</div></section>}

function ApiAdminCalendar({blockedDates,setBlockedDates,blockedItems,setBlockedItems,notify}){const[anchor,setAnchor]=useState(new Date()),grid=getMonthGrid(anchor);const refresh=async()=>{const d=await api.loadSite();setBlockedDates(d.blockedDates);setBlockedItems(d.blocked)};const toggle=async d=>{const iso=dateKey(d),item=blockedItems.find(x=>x.date===iso);try{if(item)await api.unblockDate(item.id);else await api.blockDate(iso,'غیرفعال‌شده توسط مدیر');await refresh();notify('تقویم کاری روی سرور ذخیره شد')}catch(err){notify(err.message)}};return <section className="panel calendar-panel"><div className="panel-title"><div><h3>تقویم کاری متصل به سرور</h3><small>روز انتخاب‌شده بلافاصله برای رزرو کاربران فعال یا غیرفعال می‌شود.</small></div></div><div className="admin-calendar"><div className="calendar-header"><button onClick={()=>setAnchor(a=>shiftPersianMonth(a,-1))}><ChevronLeft/></button><h2>{grid.title}</h2><button onClick={()=>setAnchor(a=>shiftPersianMonth(a,1))}><ChevronLeft className="flip"/></button></div><div className="weekdays">{['شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه'].map(x=><span key={x}>{x}</span>)}</div><div className="month-days">{grid.days.map((d,i)=>d?<button key={dateKey(d)} disabled={d.getDay()===5} className={blockedDates.includes(dateKey(d))||d.getDay()===5?'blocked':''} onClick={()=>toggle(d)}><strong>{new Intl.DateTimeFormat('fa-IR-u-ca-persian',{day:'numeric'}).format(d)}</strong><small>{d.getDay()===5?'تعطیل':blockedDates.includes(dateKey(d))?'غیرفعال':'قابل رزرو'}</small></button>:<span className="empty-day" key={i}/>)}</div></div></section>}

function ApiCertificateManager({certificates,setCertificates,notify}){const empty={title:'',issuer:'',year:persianParts(new Date()).year,code:'',description:'',skills:'',image:'/assets/hero-salon.jpg',type:'image'};const[form,setForm]=useState(empty),[file,setFile]=useState(null);const add=async e=>{e.preventDefault();try{let next={...form};if(file){const uploaded=await api.upload(file,'certificate');next={...next,image:uploaded.src,type:uploaded.type}}const created=await api.addCertificate(next);setCertificates(x=>[...x,created]);setForm(empty);setFile(null);notify('گواهینامه روی سرور ذخیره شد')}catch(err){notify(err.message)}};const remove=async id=>{await api.deleteCertificate(id);setCertificates(x=>x.filter(y=>y.id!==id))};return <div className="manager-layout"><section className="panel manager-form"><h3>افزودن مدرک</h3><form onSubmit={add}><label><span>عنوان</span><input value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label><label><span>صادرکننده</span><input value={form.issuer} onChange={e=>setForm({...form,issuer:e.target.value})}/></label><div className="inline-fields"><input value={form.year} onChange={e=>setForm({...form,year:e.target.value})}/><input placeholder="کد اعتبار" value={form.code} onChange={e=>setForm({...form,code:e.target.value})}/></div><textarea placeholder="شرح مدرک" value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/><input placeholder="مهارت‌ها با ، جدا شوند" value={form.skills} onChange={e=>setForm({...form,skills:e.target.value})}/><input type="file" accept="image/*,video/*" onChange={e=>setFile(e.target.files[0])}/><button className="primary-btn"><Plus/> ذخیره مدرک</button></form></section><section className="panel manager-list"><h3>مدارک ذخیره‌شده</h3>{certificates.map(c=><article className="manage-row" key={c.id}><span className="manage-icon"><Award/></span><div><strong>{c.title}</strong><small>{c.issuer}</small></div><button className="icon-btn danger" onClick={()=>remove(c.id)}><Trash2/></button></article>)}</section></div>}

function ApiStaffManager({staff,setStaff,notify}){const[name,setName]=useState(''),[role,setRole]=useState('');const add=async()=>{try{const created=await api.addStaff({name,role,years:'عضو تیم باران',img:'/assets/hero-salon.jpg'});setStaff(x=>[...x,created]);setName('');setRole('');notify('عضو تیم روی سرور ذخیره شد')}catch(err){notify(err.message)}};const remove=async id=>{await api.deleteStaff(id);setStaff(x=>x.filter(y=>y.id!==id))};return <section className="panel staff-manager"><div className="panel-title"><h3>مدیریت پرسنل</h3><button className="primary-btn" onClick={add}><UserPlus/> افزودن</button></div><div className="staff-add-row"><input value={name} onChange={e=>setName(e.target.value)} placeholder="نام و نام خانوادگی"/><input value={role} onChange={e=>setRole(e.target.value)} placeholder="سمت یا تخصص"/></div><div className="staff-admin-grid">{staff.map(p=><article key={p.id}><img src={p.img}/><div><span><strong>{p.name}</strong><small>{p.role}</small></span><button onClick={()=>remove(p.id)}><Trash2/></button></div></article>)}</div></section>}

function ApiSalonSettings({notify}){const[form,setForm]=useState({name:'',phone:'',mobile:'',address:'',about:'',opensAt:'09:00:00',closesAt:'20:00:00'});useEffect(()=>{api.loadSite().then(x=>x.salon&&setForm(x.salon)).catch(()=>{})},[]);const field=(key,label)=><label><span>{label}</span><input value={form[key]||''} onChange={e=>setForm({...form,[key]:e.target.value})}/></label>;const save=async()=>{try{await api.saveSalon(form);notify('اطلاعات سالن روی سرور ذخیره شد')}catch(err){notify(err.message)}};return <section className="panel settings-panel"><div className="settings-grid">{field('name','نام سالن')}{field('phone','تلفن')}{field('mobile','موبایل')}<label className="wide"><span>آدرس</span><input value={form.address||''} onChange={e=>setForm({...form,address:e.target.value})}/></label><label className="wide"><span>متن معرفی</span><textarea value={form.about||''} onChange={e=>setForm({...form,about:e.target.value})}/></label></div><button className="primary-btn" onClick={save}><Save/> ذخیره در سرور</button></section>}

function ServiceManager({services,setServices,notify}){const empty={title:'',desc:'',price:'',duration:60,icon:'sparkles',active:true};const[form,setForm]=useState(empty);const add=e=>{e.preventDefault();if(!form.title||!form.price)return;setServices(x=>[...x,{...form,id:Date.now()}]);setForm(empty);notify('خدمت جدید به سایت اضافه شد')};return <div className="manager-layout"><section className="panel manager-form"><div className="panel-title"><div><h3>تعریف خدمت جدید</h3><small>خدمت پس از ذخیره در سایت نمایش داده می‌شود.</small></div></div><form onSubmit={add}><label><span>عنوان خدمت</span><input value={form.title} onChange={e=>setForm({...form,title:e.target.value})} placeholder="مثلاً کراتین و احیای مو"/></label><label><span>شروع قیمت (تومان)</span><input value={form.price} onChange={e=>setForm({...form,price:e.target.value})} placeholder="۱,۵۰۰,۰۰۰"/></label><div className="inline-fields"><label><span>مدت تقریبی</span><input type="number" value={form.duration} onChange={e=>setForm({...form,duration:Number(e.target.value)})}/></label><label><span>دسته‌بندی</span><select value={form.icon} onChange={e=>setForm({...form,icon:e.target.value})}><option value="sparkles">مو و رنگ</option><option value="heart">میکاپ</option><option value="scissors">کوتاهی</option><option value="star">ناخن</option></select></label></div><label><span>توضیحات</span><textarea value={form.desc} onChange={e=>setForm({...form,desc:e.target.value})}/></label><button className="primary-btn"><Plus/> افزودن خدمت</button></form></section><section className="panel manager-list"><div className="panel-title"><div><h3>خدمات تعریف‌شده</h3><small>{fa(services.length)} خدمت</small></div></div>{services.map(s=><article className="manage-row" key={s.id}><span className="manage-icon"><Scissors/></span><div><strong>{s.title}</strong><small>شروع از {s.price} تومان · {fa(s.duration)} دقیقه</small></div><label className="switch"><input type="checkbox" checked={s.active} onChange={()=>setServices(x=>x.map(y=>y.id===s.id?{...y,active:!y.active}:y))}/><i/></label><button className="icon-btn danger" onClick={()=>setServices(x=>x.filter(y=>y.id!==s.id))}><Trash2/></button></article>)}</section></div>}
function MediaManager({media,setMedia,notify}){const addFiles=e=>{const next=[...e.target.files].map(f=>({id:Date.now()+Math.random(),name:f.name,type:f.type.startsWith('video')?'video':'image',src:URL.createObjectURL(f),section:'گالری'}));setMedia(x=>[...next,...x]);notify(`${fa(next.length)} رسانه اضافه شد`)};return <section className="panel media-panel"><div className="panel-title"><div><h3>مدیریت تصاویر و ویدئوها</h3><small>برای اسلایدر، گالری، معرفی سالن و مدارک رسانه بارگذاری کنید.</small></div></div><label className="dropzone"><input type="file" accept="image/*,video/*" multiple onChange={addFiles}/><UploadCloud/><h3>تصاویر و ویدئوها را اینجا رها کنید</h3><p>یا برای انتخاب فایل کلیک کنید</p><small>JPG, PNG, WEBP, MP4</small></label><div className="media-toolbar"><h3>کتابخانه رسانه</h3><span>{fa(media.length)} فایل</span></div><div className="media-grid">{media.map(m=><article key={m.id}>{m.type==='video'?<div className="video-thumb"><img src={m.src}/><Play/></div>:<img src={m.src} alt={m.name}/>}<div><span>{m.type==='video'?<Video/>:<Camera/>}</span><small>{m.name}</small><button onClick={()=>setMedia(x=>x.filter(y=>y.id!==m.id))}><Trash2/></button></div></article>)}</div></section>}
function CertificateManager({certificates,setCertificates,notify}){const empty={title:'',issuer:'',year:persianParts(new Date()).year,code:'',description:'',skills:'',image:'/assets/hero-salon.jpg',type:'image'};const[form,setForm]=useState(empty);const upload=e=>{const f=e.target.files[0];if(f)setForm({...form,image:URL.createObjectURL(f),type:f.type.startsWith('video')?'video':'image'})};const add=e=>{e.preventDefault();if(!form.title||!form.issuer)return;setCertificates(x=>[...x,{...form,id:Date.now(),skills:form.skills.split('،').map(x=>x.trim()).filter(Boolean)}]);setForm(empty);notify('مدرک جدید به رزومه اضافه شد')};return <div className="manager-layout"><section className="panel manager-form"><div className="panel-title"><div><h3>افزودن مدرک یا گواهینامه</h3><small>تصویر، ویدئو و جزئیات کامل مدرک را ثبت کنید.</small></div></div><form onSubmit={add}><label><span>عنوان مدرک</span><input value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/></label><label><span>مؤسسه صادرکننده</span><input value={form.issuer} onChange={e=>setForm({...form,issuer:e.target.value})}/></label><div className="inline-fields"><label><span>سال دریافت</span><input value={form.year} onChange={e=>setForm({...form,year:e.target.value})}/></label><label><span>کد اعتبار</span><input value={form.code} onChange={e=>setForm({...form,code:e.target.value})}/></label></div><label><span>شرح مدرک</span><textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label><label><span>مهارت‌ها (با «،» جدا کنید)</span><input value={form.skills} onChange={e=>setForm({...form,skills:e.target.value})}/></label><label className="compact-upload"><input type="file" accept="image/*,video/*" onChange={upload}/><UploadCloud/><span>بارگذاری تصویر یا ویدئوی مدرک</span></label><button className="primary-btn"><Plus/> افزودن به رزومه</button></form></section><section className="panel manager-list"><div className="panel-title"><div><h3>رزومه و مدارک</h3><small>{fa(certificates.length)} مورد</small></div></div>{certificates.map(c=><article className="manage-row cert-row" key={c.id}>{c.type==='video'&&c.image?.startsWith('blob:')?<video src={c.image}/>:<img src={c.image} alt={c.title}/>}<div><strong>{c.title}</strong><small>{c.issuer} · {c.year}</small></div><button className="icon-btn danger" onClick={()=>setCertificates(x=>x.filter(y=>y.id!==c.id))}><Trash2/></button></article>)}</section></div>}
function StaffManager({staff,setStaff,notify}){const[name,setName]=useState(''),[role,setRole]=useState('');const add=()=>{if(!name)return;setStaff(x=>[...x,{id:Date.now(),name,role:role||'متخصص زیبایی',years:'عضو تیم باران',img:'/assets/hero-salon.jpg'}]);setName('');setRole('');notify('عضو جدید به تیم اضافه شد')};return <section className="panel staff-manager"><div className="panel-title"><div><h3>مدیریت پرسنل</h3><small>اعضای تیم، تخصص و پروفایل آن‌ها</small></div><button className="primary-btn" onClick={add}><UserPlus/> افزودن عضو</button></div><div className="staff-add-row"><input value={name} onChange={e=>setName(e.target.value)} placeholder="نام و نام خانوادگی"/><input value={role} onChange={e=>setRole(e.target.value)} placeholder="سمت یا تخصص"/></div><div className="staff-admin-grid">{staff.map(p=><article key={p.id}><img src={p.img}/><div><strong>{p.name}</strong><small>{p.role}</small></div><button onClick={()=>setStaff(x=>x.filter(y=>y.id!==p.id))}><Trash2/></button></article>)}</div></section>}
function SalonSettings({notify}){return <section className="panel settings-panel"><div className="panel-title"><div><h3>اطلاعات سالن</h3><small>اطلاعات تماس و محتوای معرفی سایت</small></div></div><div className="settings-grid"><label><span>نام سالن</span><input defaultValue="سالن زیبایی باران"/></label><label><span>شماره تماس</span><input defaultValue="۰۲۱-۲۲۳۳ ۴۴۵۵"/></label><label className="wide"><span>آدرس</span><input defaultValue="تهران، پاسداران، بوستان هشتم، پلاک ۲۴"/></label><label><span>ساعت شروع</span><input type="time" defaultValue="09:00"/></label><label><span>ساعت پایان</span><input type="time" defaultValue="20:00"/></label><label className="wide"><span>متن معرفی سالن</span><textarea defaultValue="فضایی برای آرامش، زیبایی و درخشش تو. در باران، هر مراجعه شروع یک حس خوب است."/></label></div><button className="primary-btn" onClick={()=>notify('اطلاعات سالن ذخیره شد')}><Save/> ذخیره اطلاعات</button></section>}
function ApiDashboard({setTab,services,staff,blockedDates}){const[items,setItems]=useState([]);useEffect(()=>{api.getAppointments().then(setItems).catch(()=>setItems([]))},[]);const today=dateKey(new Date()),todayCount=items.filter(x=>dateKey(new Date(x.startsAt))===today).length,pending=items.filter(x=>x.status==='Pending').length;return <div className="dashboard"><div className="metric-grid"><article><span className="pink"><CalendarDays/></span><div><small>نوبت‌های امروز</small><strong>{fa(todayCount)}</strong><em>بر اساس اطلاعات ثبت‌شده</em></div></article><article><span className="gold"><UsersRound/></span><div><small>نوبت‌های در انتظار</small><strong>{fa(pending)}</strong><em>نیازمند بررسی مدیر</em></div></article><article><span className="purple"><Scissors/></span><div><small>خدمات فعال</small><strong>{fa(services.filter(x=>x.active).length)}</strong><em>تعریف‌شده در پنل</em></div></article><article><span className="green"><UsersRound/></span><div><small>پرسنل فعال</small><strong>{fa(staff.filter(x=>x.active!==false).length)}</strong><em>{fa(blockedDates.length)} روز غیرفعال</em></div></article></div><div className="admin-row"><ApiAppointments/><div className="quick"><h3>دسترسی سریع</h3><button onClick={()=>setTab('calendar')}><Clock3/><span><strong>تقویم کاری</strong><small>مدیریت روزهای قابل رزرو</small></span><ChevronLeft/></button><button onClick={()=>setTab('services')}><DollarSign/><span><strong>خدمات و قیمت‌ها</strong><small>تعریف و ویرایش خدمات</small></span><ChevronLeft/></button><button onClick={()=>setTab('sms')}><MessageCircle/><span><strong>تنظیمات پیامک</strong><small>مدیر، مشتری و درگاه ارسال</small></span><ChevronLeft/></button></div></div></div>}
function ApiSmsSettings({notify}){const empty={adminMobile:'',apiKey:'',sender:'',isEnabled:false,customerTemplate:'نوبت شما برای {ServiceTitle} در تاریخ {Date} ساعت {Time} ثبت شد.',managerTemplate:'نوبت جدید: {CustomerName}، {Mobile}، {ServiceTitle}، {Date} ساعت {Time}'};const[form,setForm]=useState(empty),[hasKey,setHasKey]=useState(false),[testMobile,setTestMobile]=useState('');useEffect(()=>{api.getSmsSettings().then(x=>{setForm({...x,apiKey:''});setHasKey(x.hasApiKey)}).catch(e=>notify(e.message))},[]);const save=async()=>{try{const x=await api.saveSmsSettings(form);setHasKey(x.hasApiKey);setForm({...x,apiKey:''});notify('تنظیمات پیامک ذخیره شد')}catch(e){notify(e.message)}};const test=async()=>{try{await api.testSms(testMobile);notify('پیامک آزمایشی ارسال شد')}catch(e){notify(e.message)}};return <section className="panel settings-panel"><h3>تنظیمات پیامک نوبت‌ها</h3><p className="sms-help">درگاه فعلی کاوه‌نگار است. متغیرهای مجاز: {'{CustomerName}'}، {'{Mobile}'}، {'{ServiceTitle}'}، {'{Date}'} و {'{Time}'}.</p><div className="settings-grid"><label><span>شماره موبایل مدیر</span><div className="phone-field"><Phone/><input type="tel" inputMode="numeric" dir="ltr" placeholder="09xxxxxxxxx" value={form.adminMobile} onChange={e=>setForm({...form,adminMobile:e.target.value})}/></div></label><label><span>شماره خط ارسال</span><div className="phone-field"><MessageCircle/><input type="tel" inputMode="numeric" dir="ltr" placeholder="شماره خط خدماتی" value={form.sender} onChange={e=>setForm({...form,sender:e.target.value})}/></div></label><label><span>کلید API کاوه‌نگار</span><input type="password" value={form.apiKey} placeholder={hasKey?'کلید قبلی محفوظ است':''} onChange={e=>setForm({...form,apiKey:e.target.value})}/></label><label><span>ارسال خودکار</span><select value={String(form.isEnabled)} onChange={e=>setForm({...form,isEnabled:e.target.value==='true'})}><option value="false">غیرفعال</option><option value="true">فعال</option></select></label><label className="wide"><span>متن پیام مشتری</span><textarea value={form.customerTemplate} onChange={e=>setForm({...form,customerTemplate:e.target.value})}/></label><label className="wide"><span>متن پیام مدیر</span><textarea value={form.managerTemplate} onChange={e=>setForm({...form,managerTemplate:e.target.value})}/></label></div><div className="sms-footer"><div className="sms-test-card"><div className="sms-test-title"><MessageCircle/><span><strong>آزمایش اتصال پیامک</strong><small>یک شماره موبایل وارد کنید تا صحت تنظیمات بررسی شود.</small></span></div><div className="sms-test-controls"><div className="phone-field"><Phone/><input type="tel" inputMode="numeric" dir="ltr" placeholder="09xxxxxxxxx" value={testMobile} onChange={e=>setTestMobile(e.target.value)}/></div><button className="ghost-btn sms-test-btn" onClick={test} disabled={!testMobile}>ارسال پیامک تست</button></div></div><div className="sms-save-bar"><small>پس از ذخیره، ارسال خودکار طبق وضعیت انتخاب‌شده انجام می‌شود.</small><button className="primary-btn" onClick={save}><Save/> ذخیره تنظیمات پیامک</button></div></div></section>}function Footer({onBooking}){const year=persianParts(new Date()).year;return <footer><div className="container footer-grid"><div><Logo/><p>فضایی برای آرامش، زیبایی و درخشش تو. در باران، هر مراجعه شروع یک حس خوب است.</p><div className="socials"><a href="#"><Instagram/></a><a href="#"><MessageCircle/></a></div></div><div><h4>دسترسی سریع</h4><button onClick={()=>scrollToId('services')}>خدمات</button><button onClick={()=>scrollToId('about')}>درباره ما</button><button onClick={()=>scrollToId('team')}>تیم باران</button></div><div className="footer-cta"><h3>آماده‌ای بدرخشی؟</h3><p>نوبتت را همین حالا، در کمتر از یک دقیقه رزرو کن.</p><button className="primary-btn" onClick={onBooking}>رزرو نوبت <ArrowLeft/></button></div></div><div className="copyright container"><span>© {year} سالن زیبایی باران — تمامی حقوق محفوظ است.</span><span>طراحی شده با <Heart fill="currentColor"/> برای زیبایی شما</span></div></footer>}
function App(){const[booking,setBooking]=useState(false),[admin,setAdmin]=useState(false),[detail,setDetail]=useState(null),[salon,setSalon]=useState(null),[services,setServices]=useState(initialServices),[certificates,setCertificates]=useState(initialCertificates),[staff,setStaff]=useState(initialStaff),[media,setMedia]=useState(initialMedia),[blockedDates,setBlockedDates]=useState([]),[blockedItems,setBlockedItems]=useState([]);useEffect(()=>{api.loadSite().then(data=>{setServices(data.services);setStaff(data.staff);setCertificates(data.certificates);setMedia(data.media);setSalon(data.salon);setBlockedDates(data.blockedDates);setBlockedItems(data.blocked)}).catch(()=>{})},[]);if(admin)return <AdminPanel onClose={()=>setAdmin(false)} services={services} setServices={setServices} certificates={certificates} setCertificates={setCertificates} staff={staff} setStaff={setStaff} media={media} setMedia={setMedia} blockedDates={blockedDates} setBlockedDates={setBlockedDates} blockedItems={blockedItems} setBlockedItems={setBlockedItems}/>;return <><Header onBooking={()=>setBooking(true)} onAdmin={()=>setAdmin(true)}/><main><Hero onBooking={()=>setBooking(true)}/><Services services={services} onBooking={()=>setBooking(true)}/><About onVideo={()=>setDetail(media.find(x=>x.type==='video'))}/><Team staff={staff} onSelect={setDetail}/><Credentials certificates={certificates} onSelect={setDetail}/><Gallery media={media} onSelect={setDetail}/><Contact salon={salon}/></main><Footer onBooking={()=>setBooking(true)}/>{booking&&<ApiBookingModal services={services} blockedDates={blockedDates} onClose={()=>setBooking(false)}/>}<DetailModal item={detail} onClose={()=>setDetail(null)}/><button className="floating-book" onClick={()=>setBooking(true)}><CalendarDays/><span>رزرو نوبت</span></button></>}
createRoot(document.getElementById('root')).render(<App/>);







